// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }
    function testFuzz_property(bytes calldata data) public {
        vm.assume(data.length <= 512);
        SelfAware helper = new SelfAware();
        bool ok;
        try c.forward(address(helper), data) { ok = true; } catch { ok = false; }
        assertTrue(ok, "forward to benign callee must succeed");
    }
}

contract SelfAware {
    address private me;
    constructor() { me = address(this); }
    fallback() external {
        // running in own context (plain call): address(this) == me -> succeed
        // running in delegate context (delegatecall into C): address(this) != me -> revert
        require(address(this) == me);
    }
}
